entries[1215613] = { ["name"] = "Paladinklassenset, Heilig, 11.1, 4 Teile", ["text"] = "Wenn 'Göttlicher Glockenschlag' Verbündete 8 Sek. lang heilt, werden diese mit Versicherung! belegt. Die Abklingzeit von 'Göttlicher Glockenschlag' wird jedes Mal, wenn Ihr Heilige Kraft verbraucht, um 1.0 Sek. verringert.\n(500ms Abklingzeit)" }
entries[1215616] = { ["name"] = "Unkontrollierter Ansturm", ["text"] = "Sofort\nBront rast auf sein Ziel zu, fügt allen Spielercharakteren auf seinem Weg 7273348 körperlichen Schaden zu und betäubt sie für 2 Sek.\n\nBronts Angriff ist so stark, dass er alle tickenden Zeitbomben auf seinem Weg wegschleudert." }
entries[1215618] = { ["name"] = "Explosives Geschenk", ["text"] = "100 Meter Reichweite\nSofort\nDie Bombe explodiert und fügt Spielercharakteren im Effektbereich Feuerschaden zu." }
entries[1215619] = { ["name"] = "Druidenklassenset, Wiederherstellung, 11.1, 4 Teile", ["text"] = "Euer 'Blühendes Leben' hat eine Chance von 30%, das Ziel für 10 Sek. mit Versicherung! zu belegen. Wenn Versicherung! verbraucht oder entfernt wird, hinterlässt sie auf ihrem Ziel für 15 Sek. einen regelmäßigen Heilungseffekt von 'Verjüngung', 'Nachwachsen' oder 'Wildwuchs', der aktuell nicht aktiv ist." }
entries[1215620] = { ["name"] = "Cho beschwören" }
entries[1215621] = { ["name"] = "Priesterklassenset, Disziplin, 11.1, 4 Teile", ["text"] = "Wenn Euer 'Machtwort: Schild' bei einem Verbündeten vollständig absorbiert wird, erhält dieser eine Versicherung! mit einer Effektivität von 40%. Verbündete mit Eurer Versicherung! oder Euren Absorptionseffekten erhalten von Euch eine um 15% erhöhte Heilung." }
entries[1215622] = { ["name"] = "Sprecht mit Lehrensucher Cho", ["text"] = "Sofort\nStellt Lehrensucher Cho eine Frage, etwa wohin Ihr als Nächstes gehen solltet oder nach mehr Informationen zur Geschichte." }
entries[1215623] = { ["name"] = "Priesterklassenset, Heilig, 11.1, 4 Teile", ["text"] = "Euer 'Segenswort: Epiphanie' und 'Segenswort: Heiligung' wenden Versicherung! für 10 Sek. auf ein Ziel an, während 'Apotheose' aktiv ist. Eure Heilung wird für jede bei Verbündeten aktive Versicherung! um 1% erhöht." }
entries[1215624] = { ["name"] = "Magierklassenset, Arkan, 11.1, 4 Teile", ["text"] = "Wenn Ihr einen Volltreffer! landet, erhaltet Ihr außerdem 3 Stapel für 'Äthereinstimmung'." }
entries[1215627] = { ["name"] = "Goblomagnetische Hüpfgranate", ["text"] = "100 Meter Reichweite\nSofort\nBrann hat eine Chance, im Kampf eine goblomagnetische Hüpfgranate auf ein Ziel zu werfen, die mäßigen Naturschaden verursacht und eine Chance von 20% hat, das Ziel für 1.5 Sek. zu betäuben. Anschließend besteht eine Chance von 25%, dass die Granate zu einem neuen Ziel hüpft.\n\nDie Granate kann bedenkenlos zu Gruppenmitgliedern springen." }
entries[1215628] = { ["name"] = "Giftsporen" }
entries[1215629] = { ["name"] = "Magierklassenset, Frost, 11.1, 4 Teile", ["text"] = "Mit dem Einsatz von 'Eisige Adern' landet Ihr 30 Sek. lang alle 10 Sek. einen Volltreffer! mit 100% Effektivität." }
