entries[1215632] = { ["name"] = "Magierklassenset, Feuer, 11.1, 4 Teile", ["text"] = "Wenn Ihr einen Volltreffer! landet, wird Euer Schaden 7 Sek. lang um 8% erhöht. Wenn Ihr mit 'Einäschern' einen Volltreffer! landen würdet, wird die Dauer um 100% erhöht." }
entries[1215633] = { ["name"] = "Jägerklassenset, Treffsicherheit, 11.1, 2 Teile", ["text"] = "Ca. 3 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Volltreffer! zu landen, der den Schaden Eurer automatischen Schüsse 10 Sek. lang um 200% erhöht und die Zeit zwischen automatischen Schüssen um 0.5 Sek. verringert. Der Einsatz der Jägerfähigkeit 'Volltreffer' landet immer einen Volltreffer!" }
entries[1215634] = { ["name"] = "Jägerklassenset, Tierherrschaft, 11.1, 2 Teile", ["text"] = "Ca. 0.4 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Volltreffer! zu landen, der einen 'Stachelpfeil' mit 100% Effektivität abfeuert. Der Einsatz von 'Zorn des Wildtiers' landet immer einen Volltreffer! ." }
