entries[1215637] = { ["name"] = "Meister Lock-und-Stock", ["text"] = "Sofort\nEure Zauber und Fähigkeiten haben eine hohe Chance, Euer Ziel für ' Präzisionssprengung ' zu markieren, was Meister Lock-und-Stock herbeiruft, der Eurem Ziel ( 4266 * 1 ) körperlichen Schaden zufügt." }
