entries[1215644] = { ["name"] = "Jägerklassenset, Tierherrschaft, 11.1, 4 Teile", ["text"] = "Ca. 1 Procs pro Minute\nEin Volltreffer! verabreicht Eurem Begleiter ein Mutagen, sodass dessen automatische Angriffe 8 Sek. lang dem Ziel und bis zu 4 Gegnern innerhalb von 10 Metern (12% der Angriffskraft) Naturschaden zufügen. Mutagene Angriffe verringern die Abklingzeit von 'Zorn des Wildtiers' um 0.10 Sek." }
entries[1215645] = { ["name"] = "Jägerklassenset, Treffsicherheit, 11.1, 4 Teile", ["text"] = "Ca. 1 Procs pro Minute\nBeim Verbrauchen von 'Sichern und Laden' wird auch ein 'Explosivschuss' mit 125% Effektivität abgefeuert." }
entries[1215647] = { ["name"] = "Schießen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nEin Kumpane feuert seinen Lavawerfer auf einen Spielercharakter ab und verursacht 52280 Feuerschaden." }
entries[1215659] = { ["name"] = "Goblomagnetische Hüpfgranate", ["text"] = "100 Meter Reichweite\nSofort\nBrann hat eine Chance, im Kampf eine goblomagnetische Hüpfgranate auf ein Ziel zu werfen, die mäßigen Naturschaden verursacht und eine Chance von 20% hat, das Ziel für 1.5 Sek. zu betäuben. Anschließend besteht eine Chance von 25%, dass die Granate zu einem neuen Ziel hüpft.\n\nDie Granate kann bedenkenlos zu Gruppenmitgliedern springen." }
entries[1215660] = { ["name"] = "Toxischer Blitz", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde fügt seinem Ziel Naturschaden zu." }
entries[1215672] = { ["name"] = "Zielmarkierer", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine hohe Chance, Euer Ziel für ' Präzisionssprengung ' zu markieren, was Meister Lock-und-Stock herbeiruft, der Eurem Ziel ( 4266 * 1 ) körperlichen Schaden zufügt." }
entries[1215673] = { ["name"] = "Ölfleck", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nWenn der Mech des Lorenbosses Schaden erleidet, verliert er Öl, auf dem Spielercharaktere herumrutschen." }
entries[1215674] = { ["name"] = "Ölfleck", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn der Mech des Lorenbosses Schaden erleidet, verliert er Öl, auf dem Spielercharaktere herumrutschen." }
entries[1215675] = { ["name"] = "Schamanenklassenset, Elementar, 11.1, 2 Teile", ["text"] = "Ca. 0.65 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Volltreffer! zu landen, der für 6.0 Sek. einen [ Sturmelementar : Sturm / Feuer]elementar beschwört. Der Einsatz von 'Aszendenz' landet immer einen Volltreffer!" }
entries[1215676] = { ["name"] = "Schamanenklassenset, Elementar, 11.1, 4 Teile", ["text"] = "Wenn Ihr Euren [ Sturmelementar : Sturm / Feuer]elementar beschwört oder verlängert, verursachen Eure Zauber 'Blitzschlag', 'Kettenblitzschlag', [ Sturmgewitter : 'Sturmgewitter' ]und 'Lavaeruption' 8 Sek. lang 30% mehr Schaden." }
entries[1215677] = { ["name"] = "Schlickbombe", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde schleudert Schlick auf sein Ziel und erzeugt an dessen Position eine Giftlache, die darin stehenden Spielercharakteren alle 1 Sek. Naturschaden zufügt." }
entries[1215678] = { ["name"] = "Hexenmeisterklassenset, Gebrechen, 11.1, 2 Teile", ["text"] = "Ca. 0.7 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Volltreffer! zu landen, der Euer Tempo 12 Sek. lang um 12% erhöht. Der Einsatz von 'Dunkelblick beschwören' landet immer einen Volltreffer!" }
entries[1215679] = { ["name"] = "Hexenmeisterklassenset, Dämonologie, 11.1, 2 Teile", ["text"] = "Ca. 0.5 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Volltreffer! zu landen, der einen Großen Schreckenspirscher mit 180% Effektivität beschwört. Der Einsatz von 'Dämonischen Tyrannen beschwören' landet immer einen Volltreffer!" }
entries[1215680] = { ["name"] = "Hexenmeisterklassenset, Zerstörung, 11.1, 2 Teile", ["text"] = "Ca. 1 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Volltreffer! zu landen, der eine Salve von 6 Dämonenfeuerblitzen mit 100% Effektivität abfeuert. Der Einsatz von 'Höllenbestie beschwören' landet immer einen Volltreffer!" }
entries[1215681] = { ["name"] = "Hexenmeisterklassenset, Zerstörung, 11.1, 4 Teile", ["text"] = "Ein Volltreffer! erhöht 10 Sek. lang Eure Meisterschaft um ([Quellwert] as)% und Eure Zauber profitieren maximal von 'Meisterschaft: Chaotische Energien'.", ["unresolvedValues"] = true }
entries[1215682] = { ["name"] = "Hexenmeisterklassenset, Dämonologie, 11.1, 4 Teile", ["text"] = "Der Einsatz von 'Hand von Gul'dan' sorgt dafür, dass Eure aktiven Schreckenspirscher 'Schreckensbiss' mit 10% Effektivität einsetzen. Dieser Schaden wird pro Seelensplitter, der von 'Hand von Gul'dan' verbraucht wurde, um 5% erhöht." }
entries[1215683] = { ["name"] = "Hexenmeisterklassenset, Gebrechen, 11.1, 4 Teile", ["text"] = "Ein Volltreffer! erhöht auch den Schaden von 'Instabiles Gebrechen' um 50% und sorgt 12 Sek. lang dafür, dass sich 'Instabiles Gebrechen' auf bis zu 3 Ziele innerhalb von 40 Metern ausbreitet." }
entries[1215684] = { ["name"] = "Schlickbombe", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde schleudert Schlick auf sein Ziel und erzeugt an dessen Position eine Giftlache, die darin stehenden Spielercharakteren alle 1 Sek. Naturschaden zufügt." }
entries[1215686] = { ["name"] = "Schlickbombe", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde schleudert Schlick auf sein Ziel und erzeugt an dessen Position eine Giftlache, die darin stehenden Spielercharakteren alle 1 Sek. Naturschaden zufügt." }
entries[1215687] = { ["name"] = "Ruferklassenset, Verheerung, 11.1, 2 Teile", ["text"] = "Ca. 2 Procs pro Minute\nEure Schadenszauber haben eine Chance, einen Volltreffer! zu landen. Dadurch geht ein 'Zerschmetternder Stern' mit 50% Effektivität auf 3 Gegner in der Nähe nieder. Beim Einsatz von 'Drachenwut' wird immer ein Volltreffer! gelandet." }
entries[1215689] = { ["name"] = "Ruferklassenset, Verstärkung, 11.1, 2 Teile", ["text"] = "Ca. 1.3 Procs pro Minute\nEure Schadenszauber haben eine Chance, einen Volltreffer! zu landen. Das löst ein 'Emporstoßen' mit 100% Effektivität aus, das Gegner nicht in die Luft wirbelt. Beim Einsatz von 'Atem der Äonen' wird immer ein Volltreffer! gelandet." }
entries[1215690] = { ["name"] = "Präzisionszielerfassung", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine hohe Chance, Euer Ziel für ' Präzisionssprengung ' zu markieren, was Meister Lock-und-Stock herbeiruft, der Eurem Ziel ( 4266 * 1 ) körperlichen Schaden zufügt." }
entries[1215691] = { ["name"] = "Ruferklassenset, Verstärkung, 11.1, 4 Teile", ["text"] = "Euer 'Emporstoßen' hat eine Chance von 50%, 'Essenzexplosion' zu gewähren. Eine mit 'Essenzexplosion' eingesetzte 'Eruption' verursacht 25% mehr Schaden.\n(Procchance: 50%)" }
entries[1215692] = { ["name"] = "Ruferklassenset, Verheerung, 11.1, 4 Teile", ["text"] = "Der Einsatz von 'Zerschmetternder Stern' oder ein Volltreffer! erhöht den Schaden Eures nächsten ermächtigten Zaubers um 18%. Bis zu 2-mal stapelbar." }
entries[1215693] = { ["name"] = "Glibberschuss", ["text"] = "100 Meter Reichweite\nWirken in 2 sek. 3 sek. Abklingzeit\nDer Zaubernde fügt seinem Ziel Naturschaden zu." }
entries[1215695] = { ["name"] = "Druidenklassenset, Gleichgewicht, 11.1, 2 Teile", ["text"] = "Ca. 2 Procs pro Minute\nEure Schaden verursachenden Zauber haben die Chance, einen Volltreffer zu landen, der bei einem Gegner in der Nähe einen 'Wildpilz' mit 100% Effektivität wachsen lassen. Wenn Ihr 'Himmlische Ausrichtung' oder 'Inkarnation: Erwählter der Elune' einsetzt, knackt Ihr immer einen Jackpot!" }
entries[1215698] = { ["name"] = "Druidenklassenset, Gleichgewicht, 11.1, 4 Teile", ["text"] = "Der Schaden von 'Sternenregen' und 'Sternensog' ist gegen Ziele, die vom regelmäßigen Schaden von Eurem 'Wildpilz' betroffen sind, um 20% erhöht." }
entries[1215702] = { ["name"] = "Priesterklassenset, Schatten, 11.1, 2 Teile", ["text"] = "Ca. 1.5 Procs pro Minute\nEure Schaden verursachenden Zauber haben eine Chance, einen Volltreffer zu landen, der einen 'Leerenblitz' mit einer Effektivität von 100% auf einen Gegner abfeuert. Wenn Ihr 'Dunkler Aufstieg' oder 'Leereneruption' einsetzt, knackt Ihr immer einen Jackpot!" }
entries[1215703] = { ["name"] = "Priesterklassenset, Schatten, 11.1, 4 Teile", ["text"] = "Wenn Ihr einen Volltreffer! landet, erhaltet Ihr 5.0 Sek. lang 'Seele der Macht'. 'Gedankenschlag' und 'Leerenblitz' verursachen 10% mehr Schaden, während 'Seele der Macht' aktiv ist." }
entries[1215704] = { ["name"] = "Betäuben", ["text"] = "100 Meter Reichweite\nSofort\nGlibb macht einen Aufstand, fügt Gegnern in der Nähe gewaltigen körperlichen Schaden zu und hat eine Chance, sie für 3 Sek. zu betäuben." }
entries[1215707] = { ["name"] = "Paladinklassenset, Vergeltung, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Urteil des Templers' und 'Göttlicher Sturm' um 2% erhöht und bis zu 10-mal stapelbar ist. 'Urteil des Templers' und 'Göttlicher Sturm' haben eine Chance von 12%, Eure Siegesserie! zu entfernen." }
entries[1215709] = { ["name"] = "Paladinklassenset, Vergeltung, 11.1, 4 Teile", ["text"] = "Wenn Ihr Eure Siegesserie! verliert, erhaltet Ihr die zuletzt verbrauchte Heilige Kraft zurück, könnt die nächsten 4.0 Sek. lang keine Heilige Kraft verlieren, und der Schaden Eurer Heilige Kraft verbrauchenden Fähigkeiten wird um 10% erhöht." }
entries[1215710] = { ["name"] = "Schamanenklassenset, Verstärkung 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Sturmschlag', 'Lavapeitsche' und 'Schicksalswinde' um 5% erhöht, insgesamt um bis zu 25%. 'Waffe des Mahlstroms' verbrauchende Fähigkeiten haben eine Chance von 1.0%, Eure Siegesserie! pro verbrauchte 'Waffe des Mahlstroms' zu entfernen." }
entries[1215711] = { ["name"] = "Frage stellen", ["text"] = "Sofort\nStellt dem Geschichtenerzähler eine Frage, etwa wohin Ihr als Nächstes gehen solltet oder nach mehr Informationen zur Geschichte." }
entries[1215712] = { ["name"] = "Schamanenklassenset, Verstärkung, 11.1, 4 Teile", ["text"] = "Wenn ihr Eure Siegesserie! verliert, verwandeln sich die Winde für 3 Sek. in 'Schicksalswinde'. Wenn 'Schicksalswinde' Schaden verursachen, verursacht Euer nächster Einsatz von 'Tobende Blitze' 12.0% mehr Schaden, bis zu 60.0%. Dieser Effekt kann bis zu 10 Stapel gespeichert werden. Außerdem fügt der Einsatz von 'Tobende Blitze' Eurem Hauptziel 75% mehr Schaden zu.\n(100ms Abklingzeit)" }
entries[1215713] = { ["name"] = "Kriegerklassenset, Waffen, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Fähigkeiten haben eine Chance, eine Siegesserie! zu starten, die den Schaden von 'Überwältigen' um 5% erhöht und bis zu 10-mal stapelbar ist.\n'Überwältigen' hat eine Chance von 15%, Eure Siegesserie! zu beenden." }
entries[1215714] = { ["name"] = "Kriegerklassenset, Furor, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Fähigkeiten haben eine Chance, eine Siegesserie! zu starten, die den Schaden von 'Toben' um 2% erhöht und bis zu 10-mal stapelbar ist.\n'Toben' hat eine Chance von 15%, Eure Siegesserie! zu beenden." }
entries[1215715] = { ["name"] = "Kriegerklassenset, Furor, 11.1, 4 Teile", ["text"] = "Wenn Ihr einen Stapel von Siegesserie! erhaltet, habt Ihr eine ausgeglichene Chance, dass entweder Euer nächster 'Blutdurst'15% mehr Schaden verursacht und eine um 25% erhöhte Chance auf einen kritischen Treffer hat oder dass Euer nächster 'Wütender Schlag' 15% mehr Schaden verursacht und 2 zusätzliche Wut erzeugt." }
entries[1215716] = { ["name"] = "Kriegerklassenset, Waffen, 11.1, 4 Teile", ["text"] = "Wenn Eure 'Siegesserie!' endet, wird Euer Tempo um 2% und der Schaden von 'Tödlicher Stoß' und 'Spalten' um 2% pro Stapel von 'Siegesserie!' erhöht, den Ihr 12 Sek. lang hattet." }
entries[1215717] = { ["name"] = "Mönchsklassenset, Windläufer, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Tritt der aufgehenden Sonne' und 'Wirbelnder Kranichtritt' um 3% erhöht und bis zu 10-mal stapelbar ist. 'Tritt der aufgehenden Sonne' und 'Wirbelnder Kranichtritt' haben eine Chance von 15%, Eure Siegesserie! zu entfernen." }
entries[1215718] = { ["name"] = "Mönchsklassenset, Windläufer, 11.1, 4 Teile", ["text"] = "Eure Fähigkeit 'Furorfäuste' wendet 1 Stapel von Siegesserie! an, wenn sie beim Einsatz vollständig kanalisiert wurde. Der Schaden Eures nächsten Einsatzes von 'Furorfäuste' wird pro Stapel um 8% erhöht, wenn Siegesserie! entfernt wird.\n\nEure Siegesserie! wird immer entfernt, wenn die maximale Anzahl an Stapeln erreicht ist." }
entries[1215719] = { ["name"] = "Schurkenklassenset, Meucheln, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Vergiften', 'Blutung' und 'Blutroter Sturm' um 3% erhöht und bis zu 10-mal stapelbar ist. 'Vergiften', 'Blutung' und 'Blutroter Sturm' haben eine Chance von 15%, Eure Siegesserie! zu entfernen." }
entries[1215720] = { ["name"] = "Schurkenklassenset, Gesetzlos, 11.1, 2 Teile", ["text"] = "Ca. 8 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Tötung' um 6% erhöht und bis zu 5-mal stapelbar ist. 'Tötung' hat eine Chance von 15%, Eure Siegesserie! zu entfernen." }
entries[1215721] = { ["name"] = "Schurkenklassenset, Täuschung, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Ausweiden', 'Geheimtechnik' und 'Schwarzpulver' um 2% erhöht und bis zu 8-mal stapelbar ist. 'Ausweiden', 'Geheimtechnik' und 'Schwarzpulver' haben eine Chance von 15%, Eure Siegesserie! zu entfernen." }
entries[1215722] = { ["name"] = "Schurkenklassenset, Täuschung, 11.1, 4 Teile", ["text"] = "Während 'Schattentanz' aktiv ist, könnt Ihr Eure Siegesserie! nicht verlieren. Wenn Ihr einen Stapel von Siegesserie! erhalten würdet, erhaltet Ihr außerdem einen zusätzlichen Stapel, und Ihr verursacht pro Stapel von Siegesserie! 2% zusätzlichen Schattenschaden." }
entries[1215724] = { ["name"] = "Schurkenklassenset, Meucheln, 11.1, 4 Teile", ["text"] = "Wenn Eure Siegesserie! enden würde, habt Ihr stattdessen eine Chance, für 4 Sek. die maximalen Stapel von Siegesserie! zu erhalten. Diese Stapel können nicht entfernt werden und ihr Effekt ist 50% stärker, solange sie immun gegen Entfernung sind." }
entries[1215725] = { ["name"] = "Schurkenklassenset, Gesetzlos, 11.1, 4 Teile", ["text"] = "'Schicksalswürfel' hat eine um 40% erhöhte Chance, zusätzliche Kampfverstärkungen zu gewähren, und wendet außerdem für jede gewährte Kampfverstärkung 1 Stapel von Siegesserie! an.\n\nDie Stapel, die durch 'Schicksalswürfel' angewendet werden, können das normale Maximum von 5 Stapeln von Siegesserie! übersteigen." }
entries[1215726] = { ["name"] = "Todesritterklassenset, Unheilig, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Todesmantel' und 'Epidemie' um 4.5% erhöht und bis zu 10-mal stapelbar ist. 'Todesmantel' und 'Epidemie' haben eine Chance von 15%, Siegesserie! zu entfernen." }
entries[1215727] = { ["name"] = "Todesritterklassenset, Frost, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Froststoß' und 'Unaufhaltbarer Gletscher' um 4% erhöht und bis zu 6-mal stapelbar ist. 'Froststoß' und 'Unaufhaltbarer Gletscher' haben eine Chance von 7%, Eure Siegesserie! zu entfernen." }
entries[1215728] = { ["name"] = "Todesritterklassenset, Unheilig, 11.1, 4 Teile", ["text"] = "Der Einsatz von 'Dunkle Transformation' gewährt bis zu 10 Stapel von Siegesserie! . Während 'Dunkle Transformation' aktiv ist, wird die Effektivität von Siegesserie! um 100% erhöht und es besteht keine Chance mehr, dass sie zurückgesetzt wird." }
entries[1215729] = { ["name"] = "Todesritterklassenset, Frost, 11.1, 4 Teile", ["text"] = "Siegesserie! sorgt dafür, dass 'Froststoß' und 'Unaufhaltbarer Gletscher' pro Stapel eine Chance von 8% haben, 'Frostsichel' mit 30% Effektivität zu wirken. Wenn Eure Siegesserie! endet, verfallt Ihr in einen 'Mordrausch' und zaubert 'Frostsichel' mit 100% Effektivität, während Ihr 6 Sek. lang (6 * [Quellwert] astery)% Meisterschaft erlangt. 'Frostsichel' fügt außerdem dem ersten getroffenen Ziel 40% mehr Schaden zu.", ["unresolvedValues"] = true }
entries[1215730] = { ["name"] = "Jägerklassenset, Überleben, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Lauffeuerbombe' um 3% erhöht und bis zu 6-mal stapelbar ist.\n'Lauffeuerbombe' hat eine Chance von 15%, Eure Siegesserie! zu beenden.\n(Procchance: 15%)" }
entries[1215731] = { ["name"] = "Dämonenjägerklassenset, Verwüstung, 11.1, 2 Teile", ["text"] = "Ca. 15 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Klingentanz' und 'Chaosstoß' um 3% erhöht und bis zu 10-mal stapelbar ist. 'Klingentanz' und 'Chaosstoß' haben eine Chance von 15%, Siegesserie! zu entfernen." }
entries[1215732] = { ["name"] = "Unvermeidbares Opfer", ["text"] = "Siegesserie! hält 8 Sek. lang an, nachdem sie durch 'Klingentanz' oder 'Chaosstoß' aufgehoben wurde.\n\nBeim Übergang in die Dämonengestalt werden alle Stapel von Siegesserie! geopfert, um pro verbrauchtem Stapel 2% kritische Trefferchance zu erlangen. Hält 15 Sek. lang an." }
entries[1215733] = { ["name"] = "Massenvernichtung", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine hohe Chance, Eure Gegner für ' Massenvernichtung ' zu markieren, was Meister Markieren-und-Verfolgen herbeiruft, der ( 2489 * 1 ) Feuerschaden verursacht, der zwischen Eurem Ziel und Gegnern in der Nähe aufgeteilt wird." }
entries[1215734] = { ["name"] = "Druidenklassenset, Wildheit, 11.1, 2 Teile", ["text"] = "Ca. 10 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Wilder Biss', 'Zerfetzen' und 'Urzorn' um 3% erhöht und bis zu 10-mal stapelbar ist. 'Wilder Biss', 'Zerfetzen' und 'Urzorn' haben eine Chance von 15%, Siegesserie! zu entfernen. Kostenlose Einsätze von 'Wilder Biss' sind von dieser Chance ausgenommen." }
entries[1215735] = { ["name"] = "Druidenklassenset, Wildheit, 11.1, 4 Teile", ["text"] = "Wenn Ihr 'Gelüst des Eliteraubtiers' verbraucht, werdet Ihr zum 'Hauptgewinner!!!', wodurch dem Primärziel von 'Eliteraubtier' (1100% der Angriffskraft) körperlicher Schaden zugefügt wird und sich der Schaden Eurer regelmäßigen Effekte 6 Sek. lang um 16% erhöht." }
entries[1215738] = { ["name"] = "Verrottender Atem", ["text"] = "50 Meter Reichweite\nWirken in 4 sek.\nDer Zaubernde haucht verrottenden Atem auf Gegner vor sich und fügt allen getroffenen Spielercharakteren 9697798 Seuchenschaden zu." }
entries[1215741] = { ["name"] = "Mächtiges Schmettern", ["text"] = "100 Meter Reichweite\nWirken in 4 sek.\nSobald Dessia 100 Energie erreicht, entfesselt sie einen mächtigen Hieb, der allen Spielercharakteren 3879119 Naturschaden zufügt und ihre Bewegungsgeschwindigkeit 10 Sek. lang um 30% verringert." }
entries[1215747] = { ["name"] = "Letzter Wille", ["text"] = "100 Meter Reichweite\nSofort\nDer letzte Wille des Kämpfers wird von den verbleibenden Wettstreitern absorbiert, was ihren verursachten Schaden um 10% erhöht und ihnen 35 zusätzliche Energie gewährt, nachdem sie ihre mächtigen Fähigkeiten eingesetzt haben. Dieser Effekt ist stapelbar." }
