entries[1215953] = { ["name"] = "Statische Aufladung", ["text"] = "300 Meter Reichweite\nWirken in 3 sek.\nMug'Zee nutzt die Elektrizität um sich herum und stürmt los. Dabei fügt er Spielercharakteren auf seinem Pfad 6708070 körperlichen Schaden zu und zerstört alle Instanzen von ' Gefängnis des Erderschütterers ' und ' Instabile Kriecherminen '.\n\nWenn er sein Ziel erreicht, entfesselt er eine ' Kugelkanonade '." }
