entries[1215986] = { ["name"] = "Druidenklassenset, Wächter, 11.1, 2 Teile", ["text"] = "Ca. 1 Procs pro Minute\nJedes Mal, wenn Ihr Schaden erleidet, besteht die Chance, dass Lotterieglück für Euch aktiviert wird, was dazu führt, dass Ihr für 4.0 Sek. 'Überlebensinstinkte' einsetzt. Euer verursachter Schaden wird 8 Sek. lang um 15% erhöht, nachdem Lotterieglück aktiviert wurde." }
entries[1215987] = { ["name"] = "Paladinklassenset, Schutz, 11.1, 2 Teile", ["text"] = "Ca. 1 Procs pro Minute\nJedes Mal, wenn Ihr Schaden erleidet, besteht die Chance, dass Lotterieglück für Euch aktiviert wird, was dazu führt, dass Ihr für 4.0 Sek. 'Wächter der Uralten Könige' einsetzt. Euer verursachter Schaden wird 10 Sek. lang um 15% erhöht, nachdem Lotterieglück aktiviert wurde." }
entries[1215988] = { ["name"] = "Druidenklassenset, Wächter, 11.1, 4 Teile", ["text"] = "Nachdem Ihr Lotterieglück erlangt, wird nach Euren nächsten 10 Druidenfähigkeiten eine weitere Druidenfähigkeit mit 125% Effektivität eingesetzt." }
entries[1215989] = { ["name"] = "Paladinklassenset, Schutz, 11.1, 4 Teile", ["text"] = "Während Ihr Lotterieglück habt, erstattet 'Schild der Rechtschaffenen' 1 bis 3 Heilige Kraft und erhöht die Dauer von Lotterieglück um 0.5 Sek. auf bis zu 10 Sek." }
entries[1215990] = { ["name"] = "Dämonenjägerklassenset, Rachsucht, 11.1, 2 Teile", ["text"] = "Ca. 1.5 Procs pro Minute\nJedes Mal, wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr 4 Sek. lang 'Metamorphose' einsetzt und Lotterieglück erlangt, was Euren verursachten Schaden 10 Sek. lang um 15% erhöht." }
entries[1215991] = { ["name"] = "Dämonenjägerklassenset, Rachsucht, 11.1, 4 Teile", ["text"] = "Es besteht eine hohe Chance, dass die Abklingzeit von 'Die Jagd' abgeschlossen wird, wenn Ihr Lotterieglück erlangt." }
entries[1215992] = { ["name"] = "Todesritterklassenset, Blut, 11.1, 2 Teile", ["text"] = "Ca. 1.5 Procs pro Minute\nJedes Mal, wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr 4 Sek. lang 'Eisige Gegenwehr' einsetzt und Lotterieglück erlangt, was Euren verursachten Schaden 10 Sek. lang um 15% erhöht." }
