entries[1215996] = { ["name"] = "Mönchsklassenset, Braumeister, 11.1, 2 Teile", ["text"] = "Ca. 2 Procs pro Minute\nJedes Mal, wenn Ihr Schaden erleidet, besteht die Chance, dass Lotterieglück für Euch aktiviert wird, was dazu führt, dass Ihr für 6.0 Sek. 'Stärkendes Gebräu' einsetzt. Euer verursachter Schaden wird 8 Sek. lang um 15% erhöht, nachdem Lotterieglück aktiviert wurde." }
