entries[1216391] = { ["name"] = "Kanister des Mechmeisteringenieurs", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix' Experiment bedeckt betroffene Gegner und absorbiert 30 Sek. lang Heilung. Jedes Ziel steuert 10937070 Heilung zu dieser Menge bei und alle verbundenen Spielercharaktere teilen diese Last.\n\nBei Ablauf oder wenn diese Heilung verbraucht wurde, explodiert der Kanister in einer ' Detonation des Strippenziehers '." }
