entries[1216443] = { ["name"] = "Elektrischer Sturm", ["text"] = "100 Meter Reichweite\nSofort\nDer besiegte Gegner bündelt seine Restenergie in einem elektrischen Sturm, der allen Spielercharakteren alle 2 Sek. 727335 Naturschaden zufügt und ihren erlittenen Naturschaden um 20% erhöht. Dieser Effekt ist stapelbar." }
entries[1216444] = { ["name"] = "Bedrohlichere bösere Bombenexplosion", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix feuert jede Menge Explosivgeschosse auf sein Primärziel ab, was 12577631 körperlichen Schaden verursacht, und erhöht den durch 'Bedrohlichere bösere Bombenexplosion' erlittenen Schaden 1.2 Min. lang um 200%. Dieser Effekt ist stapelbar und Ausweichen oder Parieren ist nicht möglich.\n\nZusätzlich erleiden Spielercharaktere innerhalb von 30 Metern um das Primärziel 12577631 Feuerschaden und erleiden eine ' Explosionsverbrennung '. Die Geschosse detonieren (größtenteils) beim Einschlag.\n\nEinige Geschosse mitsamt ihrer Zünder verteilen sich jedoch über die Arena." }
entries[1216445] = { ["name"] = "Bedrohlichere bösere Bombenexplosion", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix feuert jede Menge Explosivgeschosse auf sein Primärziel ab, was 12577631 körperlichen Schaden verursacht, und erhöht den durch 'Bedrohlichere bösere Bombenexplosion' erlittenen Schaden 1.2 Min. lang um 200%. Dieser Effekt ist stapelbar und Ausweichen oder Parieren ist nicht möglich.\n\nZusätzlich erleiden Spielercharaktere innerhalb von 30 Metern um das Primärziel 12577631 Feuerschaden und erleiden eine ' Explosionsverbrennung '. Die Geschosse detonieren (größtenteils) beim Einschlag.\n\nEinige Geschosse mitsamt ihrer Zünder verteilen sich jedoch über die Arena." }
