entries[1217091] = { ["name"] = "Astrale Energie", ["text"] = "[Die Wickel stimmen sich auf Eure Spezialisierung ein und gewähren Euch ' Astrale Rekonstitution ':\n\nEure hilfreichen Zauber und Fähigkeiten haben eine Chance, schlummernde Energien zu sammeln, um einen Verbündeten um 1716 Gesundheit zu heilen. Überschüssige Heilung aus diesem Effekt gewährt 20 Sek. lang einen Absorptionsschild. ][Die Wickel stimmen sich auf Eure Spezialisierung ein und gewähren Euch ' Astraler Schutz ':\n\nEure Zauber und Fähigkeiten haben eine hohe Chance, die Euch umgebende Energie zu verschmelzen, um Euch einen Schild zu gewähren, der den erlittenen Schaden um 20% bis zu höchstens 2668 verringert.\n\nWenn Eure Gesundheit unter 40% sinkt, erhaltet Ihr diesen Effekt mit einer Effektivität von 500%. Dieser Effekt kann nur einmal alle 6 Min. auftreten. ][Die Wickel stimmen sich auf Eure Spezialisierung ein und gewähren Euch ' Astrales Schröpfen ':\n\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, latente Energien aus Eurer Umgebung zu fokussieren, um 1334 Arkanschaden zu verursachen, der zwischen Eurem Ziel und Gegnern in der Nähe aufgeteilt wird. Gegner mit weniger als 35% Gesundheit erleiden 20% zusätzlichen Schaden. ]" }
entries[1217092] = { ["name"] = "Sturmleiter", ["text"] = "Der Einsatz von 'Blitzschlag' oder 'Kettenblitzschlag' verringert die Abklingzeit von 'Astralverschiebung', 'Windböe', 'Windstoß' und Naturtotems um 1.0 Sek.\n\nUnterbrechungsdauer Eurer Zauber 'Blitzschlag' und 'Kettenblitzschlag' um 65% reduziert.\n(500ms Abklingzeit)" }
