entries[1217096] = { ["name"] = "Astraler Schutz", ["text"] = "Sofort\nCa. 2 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine hohe Chance, die Euch umgebende Energie zu verschmelzen, um Euch einen Schild zu gewähren, der den erlittenen Schaden um 20% bis zu höchstens 2668 verringert.\n\nWenn Eure Gesundheit unter 40% sinkt, erhaltet Ihr diesen Effekt mit einer Effektivität von 500%. Dieser Effekt kann nur einmal alle 6 Min. auftreten.\n(100ms Abklingzeit)" }
