entries[1217287] = { ["name"] = "Unterdrückung", ["text"] = "Sofort\nGallywix' feuert 3 Sek. lang Schrapnelle auf Untergebene und fügt ihnen 4192544 Feuerschaden sowie Spielercharakteren innerhalb von 2.5 Metern 9 Sek. lang alle 0.5 Sek. 586956 Feuerschaden zu. Dieser Effekt ist stapelbar." }
entries[1217290] = { ["name"] = "Wieder einen im Sack", ["text"] = "Unbegrenzte Reichweite\nSofort\nZwei in einem: ' Pionierpäckchen ' lässt zusätzliche Bomben fallen, die kurz darauf explodieren und Spielercharakteren innerhalb von 7 Metern 5031052 Feuerschaden zufügen." }
entries[1217291] = { ["name"] = "Fokussierte Detonation", ["text"] = "Unbegrenzte Reichweite\nSofort\n700-kg-Blindgängermunition verankert sich im Boden und explodiert nach 15 Sek., was allen Spielercharakteren 6708070 Feuerschaden sowie 9 Sek. lang alle 3 Sek. 2515526 zusätzlichen Feuerschaden zufügt. Dieser Effekt ist stapelbar.\n\nInteraktion mit der Munition fokussiert stattdessen die Explosion, die dann 13416139 körperlichen Schaden verursacht, eine ' Fokussierte Detonation ' und zusätzlich einen Rückstoßeffekt auslöst." }
