entries[1217528] = { ["name"] = "Stampfen", ["text"] = "100 Meter Reichweite\nSofort\nWenn Ihr 'Stachelpfeil' einsetzt, stampft Euer Begleiter auf den Boden und fügt seinem Primärziel [((60% der Angriffskraft)) * (1 + Vielseitigkeit) * 0.6 * 2] körperlichen Schaden und allen anderen Gegnern in der Nähe [((60% der Angriffskraft)) * (1 + Vielseitigkeit) * 0.6 * 2] körperlichen Schaden zu." }
entries[1217533] = { ["name"] = "Münzmagnet", ["text"] = "15 Meter Reichweite\nSofort\nBeim Erreichen von 100 Energie, aktiviert der Meuteverprügler einen starken Magneten, der alle Goldhaufen innerhalb von 15 Metern zu sich zieht und pro Münzhaufen einen Stapel von ' Pay to Win ' erhält." }
entries[1217535] = { ["name"] = "Giftige Stacheln", ["text"] = "Direkter Schaden von 'Stachelpfeil' hat eine Chance von 30%, beim Einschlag zu explodieren, 'Schlangengift' anzuwenden und Gegnern in der Nähe (120% der Angriffskraft) Naturschaden zuzufügen. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n' Schlangengift '\nFeuert einen Schuss ab, der Euer Ziel vergiftet und ihm so sofort [ Gezackte Schüsse : [(30% der Angriffskraft) * 1.1] / (30% der Angriffskraft)] Naturschaden sowie zusätzlich [ Gezackte Schüsse : [(123.6% der Angriffskraft) * 1.1] / (123.6% der Angriffskraft)] Naturschaden im Verlauf von 18 Sek. zufügt. [ Giftinjektion : Der Schaden von 'Schlangengift' ruft beim Ziel 'Latentes Gift' hervor. Dieser Effekt ist bis zu 10-mal stapelbar. ' [ Tierherrschaft : 'Stachelpfeil' / Treffsicherheit : 'Gezielter Schuss' / Überleben : 'Raptorstoß' / 'Mungobiss' ] ' zehrt alle Stapel von 'Latentes Gift' auf und fügt dem Ziel pro Stapel (20.7% der Angriffskraft) Naturschaden zu ]" }
